# Generated by GitHub Copilot - Oct-05-2026
def test_subprocess_timeout_and_bounded_output():
    """Owned children stop on timeout and large output is never loaded unbounded."""
    with pytest.raises(subprocess.TimeoutExpired):
        run_command([sys.executable,'-c','import threading; threading.Event().wait(30)'],timeout=.2)
    with pytest.raises(RuntimeError,match='limite'):
        run_command([sys.executable,'-c','print("x"*10000)'],output_limit_bytes=100)
    output,_=run_command([sys.executable,'-c','print("ok")'],timeout=5)
    assert output.strip()=='ok'


# Generated by GitHub Copilot - Oct-05-2026
def test_active_lock_is_not_removed_and_dead_owner_recovers(tmp_path,monkeypatch):
    """Recover stale locks, never override a live concurrent run."""
    from ldporto import core
    with output_lock(tmp_path):
        with pytest.raises(RuntimeError):
            with output_lock(tmp_path):
                pass
        assert (tmp_path/'RUNNING.lock').is_file()
    (tmp_path/'RUNNING.lock').write_text('99999999',encoding='ascii')
    monkeypatch.setattr(core,'process_alive',lambda pid: False)
    with output_lock(tmp_path):
        assert (tmp_path/'RUNNING.lock').read_text()==str(os.getpid())
    assert not (tmp_path/'RUNNING.lock').exists()


# Generated by GitHub Copilot - Oct-05-2026
def test_credentials_and_tracebacks_are_redacted():
    """Formatting cannot append an unsanitized exception to a safe message."""
    fake='hf_'+'z'*30
    try:
        raise ValueError(fake)
    except ValueError:
        record=logging.LogRecord('fixture',logging.ERROR,__file__,1,'native failure',(),sys.exc_info())
    text=SecretSafeFormatter('%(message)s').format(record)
    assert fake not in text
    assert 'abcdef' not in scrub('Authorization: Basic abcdef')


