def test_report_html_escapes_ids_and_rejects_remote_or_traversing_images():
    """Native/local reports must not execute metadata or request remote private data."""
    from ldporto.reports import html_report,safe_image_reference
    assert not safe_image_reference('https://external.invalid/image.jpg')
    assert not safe_image_reference('../private/image.jpg')
    data={'analysis_status':'partial','issues':[],'transcript_segments':[],
          'people':[{'person_id':'<script>invalid</script>','portrait':'thumbnails/local.jpg'}],
          'metadata':{'duration':1},'summary':{}}
    html=html_report(data)
    assert '<figcaption><script>' not in html
    assert '&lt;script&gt;invalid' in html
    assert 'Content-Security-Policy' in html and 'sha256-' in html and ':focus-visible' in html


