def test_download_cache_cannot_reference_external_video(tmp_path):
    """A cached filename cannot escape the per-video directory even with a correct hash."""
    from ldporto.media import resolve_input
    from ldporto.config import load_config
    from ldporto.core import write_json,file_hash
    directory=tmp_path/'input'/'youtube'/'abcdefghijk'
    directory.mkdir(parents=True)
    outside=tmp_path/'outside.mp4'
    outside.write_bytes(b'synthetic external data')
