def test_real_http_redirect_is_blocked_without_external_request():
    """Exercise urllib's actual redirect processing with a loopback-only HTTP server."""
    import threading
    from http.server import BaseHTTPRequestHandler,HTTPServer
    from ldporto.ollama_local import _request_json
    class RedirectFixture(BaseHTTPRequestHandler):
        """Local HTTP fixture, never a product server or remote test service."""
        def do_GET(self):
            """Return an attempted external redirect without sending source data."""
            self.send_response(302)
            self.send_header('Location','https://external.invalid/private')
            self.send_header('Content-Length','0')
            self.end_headers()
        def log_message(self,*args):
            """Keep fixture HTTP logs out of test evidence."""
            return
    server=HTTPServer(('127.0.0.1',0),RedirectFixture)
    thread=threading.Thread(target=server.serve_forever,daemon=True)
    thread.start()
    try:
        with pytest.raises(ValueError,match='Redirecionamento'):
            _request_json(f'http://127.0.0.1:{server.server_port}','/api/version',timeout=2)
    finally:
        server.shutdown()
        server.server_close()
        thread.join(timeout=2)
    assert not thread.is_alive()


